#pragma once
#include <fstream>
inline bool flushTestDialogPaintCandidate(HWND window,HDC dc){RedrawWindow(window,nullptr,nullptr,RDW_INVALIDATE|RDW_ERASE|RDW_ALLCHILDREN|RDW_UPDATENOW);const bool painted=PrintWindow(window,dc,PW_CLIENTONLY)!=FALSE;GdiFlush();return painted;}
// Capture only the test-owned dialog client; no desktop or other app pixels.
inline bool captureTestDialogCandidate(HWND window,const char*path){RECT rect{};if(!GetClientRect(window,&rect)||rect.right<=0||rect.bottom<=0)return false;auto source=GetDC(window);auto dc=CreateCompatibleDC(source);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=rect.right;info.bmiHeader.biHeight=-rect.bottom;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;void*pixels=nullptr;auto bitmap=CreateDIBSection(source,&info,DIB_RGB_COLORS,&pixels,nullptr,0);if(!source||!dc||!bitmap){if(bitmap)DeleteObject(bitmap);if(dc)DeleteDC(dc);if(source)ReleaseDC(window,source);return false;}auto previous=SelectObject(dc,bitmap);bool captured=flushTestDialogPaintCandidate(window,dc);if(captured){BITMAPFILEHEADER header{};header.bfType=0x4d42;header.bfOffBits=sizeof(header)+sizeof(info.bmiHeader);header.bfSize=header.bfOffBits+rect.right*rect.bottom*4;std::ofstream file(path,std::ios::binary);file.write(reinterpret_cast<const char*>(&header),sizeof(header));file.write(reinterpret_cast<const char*>(&info.bmiHeader),sizeof(info.bmiHeader));file.write(reinterpret_cast<const char*>(pixels),rect.right*rect.bottom*4);captured=bool(file);}SelectObject(dc,previous);DeleteObject(bitmap);DeleteDC(dc);ReleaseDC(window,source);return captured;}
